/**
 * Fast pseudo-random number generator for shadow map noise.
 * Generates deterministic noise based on 4D seed (position + iteration).
 *
 * @function noiseRandom
 * @short Fast shadow filter that uses two Poisson disk taps rotated by noise for softer shadows.
 * @category TSL
 * @tags WebGPU, WebGL
 * @tsl
 * @param {Node.<vec4>} seed4 4D seed vector for hash function.
 * @returns {Node.<float>} Random value in [0..1].
 * @private
 */
export const noiseRandom: any;
/**
 * Fast shadow map filtering using spatial noise and Poisson disk sampling.
 *
 * **Algorithm**
 * - Generates 2 Poisson disk samples per fragment
 * - Uses world-position-based noise to rotate sample pattern
 * - Reduces banding artifacts with minimal performance cost
 * - Provides softer shadow edges than standard PCF
 *
 * **Usage**
 * ```js
 * import { shadowMapFastNoise } from '@three-blocks/core';
 *
 * const dirLight = new THREE.DirectionalLight(0xffffff, 1);
 * dirLight.castShadow = true;
 * dirLight.shadow.filterNode = shadowMapFastNoise;
 * ```
 *
 * **Performance**
 * - Only 2 shadow map samples per fragment (vs 4-16 for standard PCF)
 * - Noise rotation provides perceptual quality of more samples
 * - Suitable for real-time applications
 *
 * @function shadowMapFastNoise
 * @category TSL
 * @tags WebGPU, WebGL
 * @tsl
 * @param {Object} params Shadow sampling parameters.
 * @param {Node.<Texture>} params.depthTexture Shadow depth texture.
 * @param {Node.<vec4>} params.shadowCoord Projected shadow coordinates.
 * @param {Object} params.shadow Shadow reference object containing `mapSize`.
 * @returns {Node.<float>} Shadow factor in [0..1] (0=fully shadowed, 1=fully lit).
 */
export const shadowMapFastNoise: any;
